// Some contemporary sources give research dates without verified life dates. Never label those as births.
const documentaryPeople=new Set(['benford','may','gerver','domokos','varkonyi','goodman-strauss','ferguson','ruggles','brodie','selvin','hatcher','siegrist','schettini-gherardini','ahmes','tokarsky','lelievre','monteil','weiss','wolecki','smith','myers','kaplan','baek']);
for(const p of PEOPLE) p.dateType=documentaryPeople.has(p.id)?'documentary':'lifetime';
export const personById=id=>PEOPLE.find(p=>p.id===id)||null;
export const advanceById=id=>ADVANCES.find(p=>p.id===id)||null;
export const personEvents=id=>ADVANCES.filter(e=>e.people.includes(id));
export function dateLabel(item,lang='fr') {
 const n=x=>x<0?`${-x} ${lang==='fr'?'av. notre ère':'BCE'}`:String(x);
 const prefix=item.dateType==='documentary'?(lang==='fr'?'Documents : ':'Documents: '):item.approximate?(lang==='fr'?'vers ':'c. '):'';
 if(item.start===item.end)return prefix+n(item.start);
 return prefix+n(item.start)+(item.end==null?(lang==='fr'?' à aujourd’hui':' to present'):` / ${n(item.end)}`);
}
export const historyRoute=(kind,id)=>`#history/${kind}/${id}`;
export function historyRecord(kind,id) {return kind==='people'?personById(id):kind==='advances'?advanceById(id):null;}
export function historyLinks(kind,item) {
 return [...new Set([...(item.links||[]),...(kind==='people'?personEvents(item.id).map(e=>historyRoute('advances',e.id)):item.people.map(id=>historyRoute('people',id)))])];
}
const normalize=x=>String(x).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function queryHistory(kind,{query='',topic='',from=-Infinity,to=Infinity}={}) {
 const terms=normalize(query).trim().split(/\s+/).filter(Boolean), list=kind==='people'?PEOPLE:ADVANCES;
 return list.filter(x=>x.start<=to&&(x.end??2026)>=from&&(!topic||x.topics.some(k=>k.startsWith(topic+'/'))||kind==='people'&&personEvents(x.id).some(e=>e.topics.some(k=>k.startsWith(topic+'/'))))&&terms.every(t=>normalize([x.name||x.title,x.summary,x.context,x.people?.map(id=>personById(id)?.name)].flat(Infinity).join(' ')).includes(t))).sort((a,b)=>a.start-b.start||a.id.localeCompare(b.id));
}
